@contextlib.contextmanager
def _pipepager(cmd_path: Path, cmd_params: list[str], color: bool | None=None) -> t.Iterator[tuple[t.TextIO, bool | None]]:
    """Page through text by feeding it to another program.

    Invokes the pager via :class:`subprocess.Popen` with an ``argv`` list.

    Invoking a pager through this might support colors: if piping to
    ``less`` and the user hasn't decided on colors, ``LESS=-R`` is set
    automatically.
    """
    import subprocess
    env = dict(os.environ)
    cmd_name = cmd_path.stem
    if WIN:
        cmd_name = cmd_name.casefold()
    if color is None and cmd_name == 'less':
        less_env = os.environ.get('LESS', '')
        if _less_uses_raw_mode(less_env, cmd_params):
            color = True
        elif not less_env and (not cmd_params):
            env['LESS'] = '-R'
            color = True
    c = subprocess.Popen([str(cmd_path)] + cmd_params, shell=False, stdin=subprocess.PIPE, env=env, errors='replace', text=True)
    stdin = t.cast(t.TextIO, c.stdin)
    try:
        yield (stdin, color)
    except BrokenPipeError:
        pass
    except Exception as e:
        c.terminate()
        raise e
    finally:
        try:
            stdin.close()
        except BrokenPipeError:
            pass
        while True:
            try:
                c.wait()
            except KeyboardInterrupt:
                pass
            else:
                break

